intfalsefile_put_contents stringfilename mixeddata intflags0 resourcenullcontext&null;
Questa funzione equivale a chiamare in successione fopen, fwrite e fclose per scrivere dati in un file.
Se filename non esiste, il file viene creato. In caso contrario, il file esistente viene sovrascritto, a meno che il flag FILE_APPEND non sia impostato.

&reftitle.returnvalues;


 Questa funzione restituisce il numero di byte scritti nel file, oppure
 &false; in caso di fallimento.

&return.falseproblem;

  &reftitle.examples;



    Esempio di utilizzo semplice


<?php
$file = 'people.txt';
// Apre il file per ottenere il contenuto esistente
$current = file_get_contents($file);
// Aggiunge una nuova persona al file
$current .= "John Smith\n";
// Riscrive il contenuto nel file
file_put_contents($file, $current);
?>




    Utilizzo dei flag


<?php
$file = 'people.txt';
// La nuova persona da aggiungere al file
$person = "John Smith\n";
// Scrive il contenuto nel file,
// usando il flag FILE_APPEND per accodare il contenuto alla fine del file
// e il flag LOCK_EX per impedire a chiunque altro di scrivere nel file contemporaneamente
file_put_contents($file, $person, FILE_APPEND | LOCK_EX);
?>
